import json
D=json.load(open("/tmp/exp/ascii_raw.json"))
for slug in ["python","rust","xml","text","unknown" if False else "c"]:
    d=D[slug]
    print("===",slug,d["pretty"])
    for i,(a,b,c) in enumerate(zip(d["default"],d["custom"],d["true"])):
        texts_a=[t for _,t in a]; texts_b=[t for _,t in b]; texts_c=[t for _,t in c]
        if texts_a!=texts_b or texts_a!=texts_c:
            print(" mismatch line",i,texts_a,texts_b,texts_c)
        if i<3: print(i,a,b,c)
    # colors per token inferred
    colors={}
    for lines_def,lines_cust,lines_true in zip(d["default"],d["custom"],d["true"]):
        for (dc,dt),(cc,ct),(tc,tt) in zip(lines_def,lines_cust,lines_true):
            if cc is None: continue
            # strip ;1
            cc_core=cc[:-2] if cc.endswith(";1") else cc
            if cc_core=="39": idx=None
            elif cc_core.isdigit():
                v=int(cc_core); idx=v-30 if 30<=v<=37 else v-90+8 if 90<=v<=97 else ('?',v)
            else: idx=('?',cc)
            colors.setdefault(idx,set()).add((dc,tc))
    print("color map",colors)
PY"}

