    elif y > 9999:
        ytxt = f"+{y:06d}"
    else:
        ytxt = f"-{abs(y):06d}"
    return f"{ytxt}-{m:02d}-{d:02d}T{hh:02d}:{mm:02d}:{ss:02d}Z"

def human_time(ts, now=None):
    if now is None:
        now = time.time()
