    elif v <= 90:
        n, unit, singular = 1, "minute", "a"
    elif v <= 2700:
        n, unit, singular = max(2, v // 60), "minute", None
    elif v <= 5400:
        n, unit, singular = 1, "hour", "an"
    elif v <= 79200:
        n, unit, singular = max(2, v // 3600), "hour", None
    elif v <= 129600:
        n, unit, singular = 1, "day", "a"
    elif v <= 561600:
        n, unit, singular = max(2, v // 86400), "day", None
    elif v <= 907200:
        n, unit, singular = 1, "week", "a"
    elif v <= 2505600:
        n, unit, singular = max(2, v // 604800), "week", None
    elif v <= 3888000:
        n, unit, singular = 1, "month", "a"
    elif v <= 29808000:
