    elif v <= 47260800:
        n, unit, singular = 1, "year", "a"
    else:
        n, unit, singular = max(2, v // 31536000), "year", None
    if singular:
        return f"in {singular} {unit}" if future else f"{singular} {unit} ago"
    return f"in {n} {unit}s" if future else f"{n} {unit}s ago"

