    # Look-around / backreferences are not supported by the Rust regex crate.
    for token, msg in [
        ("(?=", "look-around, including look-ahead and look-behind, is not supported"),
        ("(?!", "look-around, including look-ahead and look-behind, is not supported"),
        ("(?<=", "look-around, including look-ahead and look-behind, is not supported"),
        ("(?<!", "look-around, including look-ahead and look-behind, is not supported"),
