        if ch == ")":
            if not depth:
                _regex_error(opt, raw, "unopened group", i)
            depth.pop()
            i += 1
            last_token_start = False
            continue
        if ch == "|":
            i += 1
            last_token_start = True
            continue
        i += 1
        last_token_start = False
