                taken = 0
                while j < n:
                    nxt = argv[j]
                    if nxt.startswith("-") and nxt not in ("-",) and len(nxt) > 1:
                        break
                    if maxv is not None and taken >= maxv:
                        break
                    add_value(opt, nxt)
                    taken += 1
                    j += 1
                if taken == 0:
                    value_required(opt)
                consumed_next = j - (i + 1)
                pos = len(chars)
