    # clap builds a usage line from the arguments already used (plus an
    # optional suggested argument) for some error kinds.
    parts = []
    seen = set()
    for key in used_keys:
        if key in seen:
            continue
        seen.add(key)
        opt = next((o for o in OPTIONS if o[0] == key), None)
        if opt:
            parts.append(_opt_usage(opt))
    if extra_opt is not None and extra_opt[0] not in seen:
        parts.append(_opt_usage(extra_opt))
    if not parts:
        return _usage_generic()
    return f"Usage: {_bin_name()} " + " ".join(parts) + " [INPUT]"

def _help_text(long=False):
    name = "help_long.txt" if long else "help_short.txt"
    data = _load_resource(name).decode("utf-8", "replace")
    data = data.replace("Usage: executable", f"Usage: {_bin_name()}", 1)
    return data

def _parse_usize(raw, opt):
    if raw == "":
        msg = "cannot parse integer from empty string"
        _invalid_value(opt, raw, msg)
    body = raw[1:] if raw.startswith("+") else raw
    if not body or any(not ch.isdigit() for ch in body):
        _invalid_value(opt, raw, "invalid digit found in string")
    value = int(body)
    if value > 18446744073709551615:
        _invalid_value(opt, raw, "number too large to fit in target type")
    return value

def _parse_color(raw, opt):
    if raw == "":
        _invalid_value(opt, raw, "cannot parse integer from empty string")
    body = raw
    sign = 1
    if body.startswith("+"):
        body = body[1:]
    elif body.startswith("-"):
        sign = -1
        body = body[1:]
    if not body or any(not ch.isdigit() for ch in body):
        _invalid_value(opt, raw, "invalid digit found in string")
    if len(body) > 19:
        _invalid_value(opt, raw, "number too large to fit in target type")
    value = sign * int(body)
    if value > 9223372036854775807 or value < -9223372036854775808:
        _invalid_value(opt, raw, "number too large to fit in target type")
    if value < 0 or value >= 16:
        _invalid_value(opt, raw, f"{value} is not in 0..16")
