def _invalid_value(opt, raw, detail=None):
    head = f"error: invalid value '{raw}' for {_opt_display(opt)}"
    if detail:
        head += f": {detail}"
    body = head + "\n"
    choices = opt[6]
    if choices:
        body += f"  [possible values: {', '.join(choices)}]\n"
        sug = best_suggestion(raw, choices)
        if sug is not None:
            body += f"\n  tip: a similar value exists: '{sug}'\n"
