    raise ClapError(body + "\nFor more information, try '--help'.\n")

def _regex_error(opt, raw, message, pos):
    caret = " " * (4 + max(0, pos)) + "^"
    detail = f"regex parse error:\n    {raw}\n{caret}\nerror: {message}"
    _invalid_value(opt, raw, detail)

def _parse_regex(raw, opt):
    # Validate with Rust-regex-like rules and return a compiled Python regex.
    # Look-around / backreferences are not supported by the Rust regex crate.
    for token, msg in [
        ("(?=", "look-around, including look-ahead and look-behind, is not supported"),
        ("(?!", "look-around, including look-ahead and look-behind, is not supported"),
        ("(?<=", "look-around, including look-ahead and look-behind, is not supported"),
        ("(?<!", "look-around, including look-ahead and look-behind, is not supported"),
    ]:
        idx = raw.find(token)
        if idx >= 0:
            _regex_error(opt, raw, msg, idx)
    # Basic structural validation for friendly errors.
    i = 0
    depth = []
    in_class = False
    class_start = -1
    last_token_start = True  # at start / after ( or |
    while i < len(raw):
        ch = raw[i]
        if ch == "\\":
            if i == len(raw) - 1:
                _regex_error(opt, raw, "incomplete escape sequence, end of input", i)
            if raw[i + 1].isdigit() and raw[i + 1] != "0":
                _regex_error(opt, raw, "backreferences are not supported", i)
            i += 2
            last_token_start = False
            continue
        if in_class:
            if ch == "]" and i != class_start + 1:
                in_class = False
            i += 1
            last_token_start = False
            continue
        if ch == "[":
            in_class = True
            class_start = i
            i += 1
            last_token_start = False
            continue
        if ch in "*+?":
            if last_token_start:
                _regex_error(opt, raw, "repetition operator missing expression", i)
            i += 1
            continue
        if ch == "{":
            # Only a repetition if it looks like {n}, {n,} or {n,m}
            m = re.match(r"\{\d*(,\d*)?\}", raw[i:])
            if m:
                if last_token_start:
                    _regex_error(opt, raw, "repetition operator missing expression", i)
                inner = m.group(0)[1:-1]
                if "," in inner:
                    a, b = inner.split(",", 1)
                    if a and b and int(a) > int(b):
                        _regex_error(opt, raw, "the range start is greater than the range end", i)
                i += len(m.group(0))
                continue
            i += 1
            last_token_start = False
            continue
        if ch == "(":
            depth.append(i)
            i += 1
            last_token_start = True
            continue
        if ch == ")":
            if not depth:
                _regex_error(opt, raw, "unopened group", i)
            depth.pop()
            i += 1
            last_token_start = False
            continue
        if ch == "|":
            i += 1
            last_token_start = True
            continue
        i += 1
        last_token_start = False
    if in_class:
        _regex_error(opt, raw, "unclosed character class", class_start)
    if depth:
        _regex_error(opt, raw, "unclosed group", depth[-1])
    py = raw
    # Translate a few Rust-only escapes Python does not know.
    py = py.replace("\\p{L}", "[A-Za-z\\u00c0-\\u024f]").replace("\\p{Letter}", "[A-Za-z\\u00c0-\\u024f]")
    try:
        return re.compile(py)
    except re.error as exc:
        _regex_error(opt, raw, str(exc.msg), exc.pos or 0)

def _validate_value(opt, raw):
    vtype = opt[5]
    choices = opt[6]
    if vtype == "usize":
        return _parse_usize(raw, opt)
    if vtype == "color":
        return _parse_color(raw, opt)
    if vtype == "regex":
        return _parse_regex(raw, opt)
    if choices is not None:
        if raw not in choices:
            _invalid_value(opt, raw)
        return raw
    return raw

def parse_args(argv):
    values = {}
    for opt in OPTIONS:
        default = opt[7]
        values[opt[0]] = list(default) if isinstance(default, list) else default
