            continue
        if token == "--":
            positional_only = True
            i += 1
            continue
        if token.startswith("--") and len(token) > 2:
            text = token[2:]
            if "=" in text:
                name, eqval = text.split("=", 1)
                has_eq = True
            else:
                name, eqval, has_eq = text, None, False
            if name == "":
                unexpected_arg("--", is_long=True, long_name="")
            if name in ("help", "version"):
                if has_eq:
                    fake = (name, None, name, None, "flag", None, None, False, None)
                    body = f"error: unexpected value '{eqval}' for '--{name}' found; no more were expected\n"
                    _clap_error(body, f"Usage: {_bin_name()} --{name} [INPUT]")
                if name == "help":
                    raise EarlyExit(_help_text(long=True))
                raise EarlyExit(f"onefetch {VERSION}\n")
            opt = OPT_BY_LONG.get(name)
            if opt is None:
                unexpected_arg(token if not has_eq else f"--{name}", is_long=True, long_name=name)
            kind = opt[4]
            if kind == "flag":
                if has_eq:
                    unexpected_value(opt, eqval)
                set_flag(opt)
                i += 1
                continue
            if kind == "optional_eq":
                mark_seen(opt)
                if has_eq:
                    values[opt[0]] = _validate_value(opt, eqval)
                else:
                    values[opt[0]] = _parse_regex(r"\[(?:bot|Bot)\]", opt)
                i += 1
                continue
            mark_seen(opt)
            maxv = opt[8]
            if has_eq:
                add_value(opt, eqval)
                i += 1
                continue
            # Need value(s) from following tokens
            if kind == "single":
                if i + 1 >= n:
                    value_required(opt)
                nxt = argv[i + 1]
                if nxt.startswith("-") and nxt not in ("-",) and len(nxt) > 1:
                    unexpected_arg(nxt, is_long=nxt.startswith("--"), long_name=nxt[2:].split("=")[0] if nxt.startswith("--") else None)
                add_value(opt, nxt)
                i += 2
                continue
            # multi
            j = i + 1
            taken = 0
            while j < n:
                nxt = argv[j]
                if nxt.startswith("-") and nxt not in ("-",) and len(nxt) > 1:
                    break
                if maxv is not None and taken >= maxv:
                    break
                add_value(opt, nxt)
                taken += 1
                j += 1
            if taken == 0:
                value_required(opt)
            i = j
            continue
        if token.startswith("-") and len(token) > 1:
            # Short options, possibly combined
            chars = token[1:]
            pos = 0
            consumed_next = 0
            while pos < len(chars):
                ch = chars[pos]
                if ch == "h":
                    raise EarlyExit(_help_text(long=False))
                if ch == "V":
                    raise EarlyExit(f"onefetch {VERSION}\n")
                opt = OPT_BY_SHORT.get(ch)
                if opt is None:
                    unexpected_arg(f"-{ch}")
                kind = opt[4]
                if kind == "flag":
                    set_flag(opt)
                    pos += 1
                    continue
                # value option: rest of token is the value, or following args
                mark_seen(opt)
                rest = chars[pos + 1:]
                maxv = opt[8]
                if rest:
                    if rest.startswith("="):
                        rest = rest[1:]
                    add_value(opt, rest)
                    pos = len(chars)
                    break
                if kind == "single":
                    if i + 1 >= n:
                        value_required(opt)
                    nxt = argv[i + 1]
                    if nxt.startswith("-") and nxt not in ("-",) and len(nxt) > 1:
                        unexpected_arg(nxt, is_long=nxt.startswith("--"), long_name=nxt[2:].split("=")[0] if nxt.startswith("--") else None)
                    add_value(opt, nxt)
                    consumed_next = 1
                    pos = len(chars)
                    break
                # multi from following tokens
                j = i + 1
                taken = 0
                while j < n:
                    nxt = argv[j]
                    if nxt.startswith("-") and nxt not in ("-",) and len(nxt) > 1:
                        break
                    if maxv is not None and taken >= maxv:
                        break
                    add_value(opt, nxt)
                    taken += 1
                    j += 1
                if taken == 0:
                    value_required(opt)
                consumed_next = j - (i + 1)
                pos = len(chars)
                break
            i += 1 + consumed_next
            continue
