        if values["input"] is None:
            if token == "":
                raise ClapError("error: a value is required for '[INPUT]' but none was supplied\n\nFor more information, try '--help'.\n")
            values["input"] = token
        else:
            unexpected_arg(token)
        i += 1
    return values

