    if ".." not in p.split("/"):
        return p
    is_abs = p.startswith("/")
    prefix_dot = p.startswith("./")
    cwd = os.getcwd()
    cwd_parts = [c for c in cwd.split("/") if c]
    parts = p.split("/")
    # Work on a stack.  For relative paths we seed nothing; when a '..'
    # underflows the relative stack we borrow components from the CWD.
    stack = []          # normal components (relative result)
    abs_stack = None    # becomes a list once the result is absolute
    if is_abs:
