# ---------------------------------------------------------------------------
# Input path handling (lexical de-dotting, like the original helper)
# ---------------------------------------------------------------------------

def parse_dot_path(p):
    """Resolve '.'/'..' components lexically, mirroring the behaviour
    exhibited by the reference binary for its INPUT argument."""
    if ".." not in p.split("/"):
        return p
    is_abs = p.startswith("/")
    prefix_dot = p.startswith("./")
    cwd = os.getcwd()
    cwd_parts = [c for c in cwd.split("/") if c]
    parts = p.split("/")
    # Work on a stack.  For relative paths we seed nothing; when a '..'
    # underflows the relative stack we borrow components from the CWD.
    stack = []          # normal components (relative result)
    abs_stack = None    # becomes a list once the result is absolute
    if is_abs:
        abs_stack = []
    underflow = 0
    for comp in parts:
        if comp in ("",):
            continue
        if comp == ".":
            # preserved only when no '..' is involved (handled earlier);
            # during de-dotting '.' components (other than a leading
            # './') are kept by the original only if untouched, but once
            # we are resolving '..' they are dropped in the rebuilt path.
            continue
        if comp == "..":
            if abs_stack is not None:
                if abs_stack:
                    abs_stack.pop()
                else:
                    raise AppError(f'Relative path "{p}"tries to reach beyond root filesystem')
            elif stack:
                stack.pop()
            else:
                underflow += 1
                if underflow > len(cwd_parts):
                    raise AppError(f'Relative path "{p}"tries to reach beyond root filesystem')
                abs_stack = cwd_parts[: len(cwd_parts) - underflow]
                # subsequent underflows keep trimming abs_stack
            continue
        if abs_stack is not None:
            abs_stack.append(comp)
        else:
            stack.append(comp)
    if abs_stack is not None:
        if not is_abs and abs_stack == cwd_parts:
            return "."
        return "/" + "/".join(abs_stack) if abs_stack else "/"
    if not stack:
        return "."
    out = "/".join(stack)
    if prefix_dot:
        out = "./" + out
    return out

