def _real_git():
    for cand in ("/usr/bin/git", "/bin/git", "/usr/local/bin/git"):
        if os.path.isfile(cand) and os.access(cand, os.X_OK):
            return cand
    found = shutil.which("git")
    return found or "git"

REAL_GIT = _real_git()

_GIT_ENV_STRIP = {
    "GIT_DIR", "GIT_WORK_TREE", "GIT_COMMON_DIR", "GIT_INDEX_FILE",
    "GIT_OBJECT_DIRECTORY", "GIT_ALTERNATE_OBJECT_DIRECTORIES",
    "GIT_NAMESPACE", "GIT_PREFIX",
}

def git_env():
    env = dict(os.environ)
    for k in _GIT_ENV_STRIP:
        env.pop(k, None)
    return env

def run_git(args, cwd, check=False, text=True):
    try:
        r = subprocess.run(
            [REAL_GIT, "-C", str(cwd)] + args,
