def _parse_cargo(text):
    try:
        try:
            import tomllib as _toml
        except Exception:
            import tomli as _toml
        data = _toml.loads(text)
    except Exception:
        return None
    if not isinstance(data, dict):
        return None
    package = data.get("package")
    if not isinstance(package, dict):
        return None
    name = package.get("name")
    if not isinstance(name, str):
        return None
    workspace = data.get("workspace") if isinstance(data.get("workspace"), dict) else {}
    ws_pkg = workspace.get("package") if isinstance(workspace, dict) else None

    def field(key):
        if key not in package:
            return None, True
        return _resolve_inherited(package.get(key), ws_pkg, key)

    desc, ok = field("description")
    if not ok or (desc is not None and not isinstance(desc, str)):
        return None
    lic, ok = field("license")
    if not ok or (lic is not None and not isinstance(lic, str)):
        return None
    ver, ok = field("version")
    if not ok or (ver is not None and not isinstance(ver, str)):
        return None
    deps = data.get("dependencies")
    if deps is None:
        count = 0
    elif isinstance(deps, dict):
        count = len(deps)
    else:
        return None
    return {
        "manager": "Cargo",
        "description": desc,
        "license": lic,
        "version": ver or "",
        "dep_count": count,
    }

