def _classify_license(text):
    norm = re.sub(r"\s+", " ", text.lower()).strip()
    if len(norm) < 100:
        return None
    # 0BSD vs ISC: both share a long sentence; the 0BSD text shipped in
    # crates says "with or without fee is hereby granted" and ISC adds
    # the "provided that" clause as part of the same sentence.  The
    # required-phrase test above for ISC is stricter, so test it first
    # via rule ordering below.
    ordered = sorted(_LICENSE_RULES, key=lambda r: -max(len(p) for p in r[1]))
    for lic_id, phrases, max_len in ordered:
        if all(p in norm for p in phrases) and len(norm) <= max_len:
            if lic_id == "BSD-2-Clause" and "neither the name of" in norm:
                continue
            return lic_id
    return None

def detect_license(workdir, manifest):
    if manifest:
        lic = manifest.get("license")
        if lic:
            return lic
    found = set()
    try:
        entries = list(os.scandir(workdir))
    except OSError:
        return ""
    for entry in entries:
        if not (entry.name.startswith("LICENSE") or entry.name.startswith("LICENCE") or entry.name.startswith("COPYING")):
            continue
        try:
            if not entry.is_file():
                continue
            text = Path(entry.path).read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        lic = _classify_license(text)
        if lic:
            found.add(lic)
    return ", ".join(sorted(found))

