# ---------------------------------------------------------------------------
# gitignore-style glob matching
# ---------------------------------------------------------------------------

def _glob_to_regex(pattern):
    """Compile a gitignore glob body (no leading '!', no trailing '/')
    into a regex that matches a whole relative path."""
    out = []
    i = 0
    n = len(pattern)
    while i < n:
        ch = pattern[i]
        if ch == "*":
            if i + 1 < n and pattern[i + 1] == "*":
                # '**' handling
                # consume run of '*'
                j = i
                while j < n and pattern[j] == "*":
                    j += 1
                prev_slash = i == 0 or pattern[i - 1] == "/"
                next_slash = j >= n or pattern[j] == "/"
                if prev_slash and next_slash:
                    if j < n and pattern[j] == "/":
                        out.append("(?:.*/)?")
                        i = j + 1
                    else:
                        out.append(".*")
                        i = j
                else:
                    out.append("[^/]*")
                    i = j
                continue
            out.append("[^/]*")
            i += 1
            continue
        if ch == "?":
            out.append("[^/]")
            i += 1
            continue
        if ch == "[":
            j = i + 1
            if j < n and pattern[j] in "!^":
                j += 1
            if j < n and pattern[j] == "]":
                j += 1
            while j < n and pattern[j] != "]":
                j += 1
            if j >= n:
                raise ValueError("unclosed character class; missing ']'")
            inner = pattern[i + 1:j]
            neg = inner.startswith("!") or inner.startswith("^")
            if neg:
                inner = inner[1:]
            inner = inner.replace("\\", "\\\\")
            out.append("[" + ("^" if neg else "") + inner + "]")
            i = j + 1
            continue
        if ch == "{":
            # brace alternation (non-gitignore in git, supported by globset)
            depth = 1
            j = i + 1
            alts = []
            cur = []
            closed = False
            while j < n:
                c = pattern[j]
                if c == "\\":
                    cur.append(pattern[j:j + 2])
                    j += 2
                    continue
                if c == "{":
                    depth += 1
                    cur.append(c)
                elif c == "}":
                    depth -= 1
                    if depth == 0:
                        closed = True
                        break
                    cur.append(c)
                elif c == "," and depth == 1:
                    alts.append("".join(cur))
                    cur = []
                else:
                    cur.append(c)
                j += 1
            if not closed:
                raise ValueError("unclosed alternate group; missing '}' (maybe escape '{' with '[{]'?)")
            alts.append("".join(cur))
            inner = "|".join(_glob_to_regex(a) for a in alts)
            out.append(f"(?:{inner})")
            i = j + 1
            continue
        if ch == "\\":
            if i + 1 >= n:
                raise ValueError("dangling '\\'")
            out.append(re.escape(pattern[i + 1]))
            i += 2
            continue
        out.append(re.escape(ch))
        i += 1
    return "".join(out)

