def _syntax_for(slug):
    return SYNTAX.get(slug, _CLike)

class CodeCounter:
    """Line-by-line code/comment/blank classifier modelled on tokei."""

    def __init__(self, slug):
        self.slug = slug
        self.line_tokens, self.blocks, self.nested, self.quotes = _syntax_for(slug)
        self.block_stack = []  # stack of end tokens
        self.string_delim = None
        self.pod = False  # perl/ruby block documentation

    def _find_in_string(self, line, i):
        delim = self.string_delim
        n = len(line)
        while i < n:
            if line[i] == "\\" and delim not in ("`",):
                i += 2
                continue
            if line.startswith(delim, i):
                return i + len(delim)
            i += 1
        return None

    def feed(self, line):
        # Perl POD / Ruby =begin blocks
        if self.slug == "perl":
            if self.pod:
                if line.startswith("=cut"):
                    self.pod = False
                return False
            if re.match(r"=[A-Za-z]", line) and not line.startswith("=="):
                self.pod = True
                return False
        if self.slug == "ruby":
            if self.pod:
                if line.startswith("=end"):
                    self.pod = False
                return False
            if line.startswith("=begin"):
                self.pod = True
                return False
        if self.slug == "fortran":
            # Legacy Fortran comment columns
            if line and line[0] in "Cc*!":
                return False
        if self.slug == "abap":
            if line.startswith("*"):
                return False

        has_code = False
        if self.string_delim is not None:
            if line != "" or self.string_delim != "`":
                has_code = True
        i = 0
        n = len(line)
        while i < n:
            if self.block_stack:
                endtok = self.block_stack[-1]
                # Find the earliest of (nested start, end)
                best = None
                best_kind = None
                best_end = None
                idx = line.find(endtok, i)
                if idx != -1:
                    best, best_kind, best_end = idx, "end", endtok
                if self.nested:
                    for start, end in self.blocks:
                        if end != endtok:
                            continue
                        sidx = line.find(start, i)
                        if sidx != -1 and (best is None or sidx < best):
                            best, best_kind, best_end = sidx, "start", start
                if best is None:
                    return has_code
                if best_kind == "start":
                    self.block_stack.append(endtok)
                    i = best + len(best_end)
                else:
                    self.block_stack.pop()
                    i = best + len(endtok)
                continue
            if self.string_delim is not None:
                nxt = self._find_in_string(line, i)
                has_code = True
                if nxt is None:
                    return has_code
                self.string_delim = None
                i = nxt
                continue
            ch = line[i]
            if ch in " \t\r\f\v":
                i += 1
                continue
            # Line comment?
            matched = False
            for tok in self.line_tokens:
                if line.startswith(tok, i):
                    return has_code
            for start, end in self.blocks:
                if line.startswith(start, i):
                    self.block_stack.append(end)
                    i += len(start)
                    matched = True
                    break
            if matched:
                continue
            for quote in self.quotes:
                if line.startswith(quote, i):
                    self.string_delim = quote
                    has_code = True
                    i += len(quote)
                    matched = True
                    break
            if matched:
                continue
            has_code = True
            i += 1
        return has_code

