                    has_code = True
                if end == -1:
                    i = n
                else:
                    mode = "html"
                    i = i + mst.end() + end
                continue
            if line[i] not in " \t\r\f\v":
                has_code = True
            i += 1
        count += 1 if has_code else 0
    return count

def count_php(text):
    count = 0
    in_php = False
    php = CodeCounter("php")
    php.line_tokens = ("//", "#")
    php.blocks = (("/*", "*/"),)
    php.quotes = ('"', "'")
    in_comment = False
    for line in _split_lines(text):
        has_code = False
        i = 0
        n = len(line)
        while i < n:
            if not in_php:
                if in_comment:
                    end = line.find("-->", i)
                    if end == -1:
                        i = n
                    else:
                        in_comment = False
                        i = end + 3
                    continue
                if line.startswith("<!--", i):
                    in_comment = True
                    i += 4
                    continue
                if line.startswith("<?php", i) or line.startswith("<?=", i) or line.startswith("<?", i):
                    in_php = True
                    has_code = True
                    i += 5 if line.startswith("<?php", i) else 2
                    continue
                if line[i] not in " \t\r\f\v":
                    has_code = True
                i += 1
            else:
                end = line.find("?>", i)
                seg = line[i:] if end == -1 else line[i:end]
                if seg and php.feed(seg):
                    has_code = True
                if end == -1:
                    i = n
                else:
                    in_php = False
                    has_code = True
                    i = end + 2
        count += 1 if has_code else 0
    return count

