def count_markdown(text):
    count = 0
    fence = None  # (char, length)
    child = None
    for line in _split_lines(text):
        stripped = line.lstrip(" ")
        indent = len(line) - len(stripped)
        if fence is not None:
            ch, flen = fence
            closing = stripped.startswith(ch * flen) and indent <= 3
            if closing:
                fence = None
                child = None
                count += 1
            else:
                if child is not None:
                    if child.feed(line):
                        count += 1
                elif line.strip() != "":
                    count += 1
            continue
        m = re.match(r"(```+|~~~+)\s*([^\s`]*)", stripped) if indent <= 3 else None
        if m:
            fence = (m.group(1)[0], len(m.group(1)))
            lang = (m.group(2) or "").lower()
            slug = _FENCE_LANG_ALIASES.get(lang)
            child = CodeCounter(slug) if slug else None
            count += 1
            continue
        if line.strip() != "":
            count += 1
    return count

def count_jupyter(data_bytes):
    try:
        nb = json.loads(data_bytes.decode("utf-8", "replace"))
    except Exception:
        return 0
    if not isinstance(nb, dict):
        return 0
    metadata = nb.get("metadata")
    if not isinstance(metadata, dict):
        return 0
    if not isinstance(metadata.get("kernelspec"), dict) or not isinstance(metadata.get("language_info"), dict):
        return 0
    cells = nb.get("cells")
    if not isinstance(cells, list):
        return 0
    lang_name = str(metadata.get("language_info", {}).get("name") or "python").lower()
    slug = _FENCE_LANG_ALIASES.get(lang_name, "python")
    total = 0
    for cell in cells:
        if not isinstance(cell, dict):
            return 0
        source = cell.get("source")
        if not isinstance(source, list) or not all(isinstance(s, str) for s in source):
            # tokei's notebook parser rejects string sources outright
            if source is not None:
                return 0
            continue
        ctype = cell.get("cell_type")
        text = "".join(source)
        lines = _split_lines(text)
        if ctype == "code":
            counter = CodeCounter(slug)
            code = sum(1 for l in lines if counter.feed(l))
            total += code * 2
        elif ctype == "markdown":
            total += sum(1 for l in lines if l.strip() != "")
        elif ctype == "raw":
            continue
        else:
            return 0
    return total

def count_code(lang, path, data_bytes):
    slug = lang.get("slug")
    if slug == "jupyter-notebooks":
        return count_jupyter(data_bytes)
    text = data_bytes.decode("utf-8", "replace")
    if slug in ("html", "vue", "svelte", "razor", "xml", "svg", "xaml", "xsl", "coldfusion"):
        if slug == "coldfusion":
            # ColdFusion comments are <!--- --->; html-like handles <!---
            return count_generic(slug, text) if False else count_html_like(text)
        return count_html_like(text)
    if slug == "markdown":
        return count_markdown(text)
    if slug == "php":
        return count_php(text)
    return count_generic(slug, text)

