_SHEBANG_ENV = {
    "python": "python", "ruby": "ruby", "groovy": "groovy",
    "groovysh": "groovy", "racket": "racket", "fish": "fish",
    "bash": "bash", "sh": "shell", "crystal": "crystal",
    "raku": "raku", "perl6": "raku", "rakudo": "raku",
}
_SHEBANG_BIN = {
    "perl": ("perl", "/usr/bin/"), "perl6": ("raku", "/usr/bin/"),
    "raku": ("raku", "/usr/bin/"), "crystal": ("crystal", "/usr/bin/"),
    "fish": ("fish", "/bin/"), "zsh": ("zsh", "/bin/"),
    "bash": ("bash", "/bin/"), "sh": ("shell", "/bin/"),
}

def _detect_shebang(first_line):
    if not first_line.startswith("#!"):
        return None
    rest = first_line[2:]
    if rest.startswith("/usr/bin/env"):
        tail = rest[len("/usr/bin/env"):]
        if tail and tail[0] in " \t":
            parts = tail.split()
            if parts:
                candidate = parts[0]
                for cmd, slug in _SHEBANG_ENV.items():
                    if candidate.startswith(cmd):
                        return LANG_BY_SLUG.get(slug)
        return None
    for cmd, (slug, prefix) in _SHEBANG_BIN.items():
        if rest.startswith(prefix + cmd):
            after = rest[len(prefix + cmd):]
            if after == "" or after[0] in " \t":
                return LANG_BY_SLUG.get(slug)
    return None

def detect_language(path, data_bytes):
    name = os.path.basename(path)
    lower = name.lower()
    if lower in _FILENAME_MAP:
        return _FILENAME_MAP[lower]
    ext = None
    if "." in name:
        head, _, tail = name.rpartition(".")
        if head != "":
            ext = tail.lower()
    if ext is not None:
        return _EXTENSION_MAP.get(ext)
    # No extension -> shebang
    first = data_bytes.split(b"\n", 1)[0].decode("utf-8", "replace")
    if first.endswith("\r"):
        first = first[:-1]
    return _detect_shebang(first)

