def parse_index_sizes(workdir, gitdir):
    index_rel = git_stdout(["rev-parse", "--git-path", "index"], workdir)
    if not index_rel:
        return 0, 0
    index_path = index_rel.rstrip("\n")
    if not os.path.isabs(index_path):
        index_path = os.path.join(workdir, index_path)
    try:
        data = Path(index_path).read_bytes()
    except OSError:
        return 0, 0
    try:
        return _parse_index_bytes(data)
    except Exception:
        # Fallback: git ls-files --debug
        r = run_git(["ls-files", "--debug", "-z"], workdir, text=False)
        if r.returncode != 0:
            return 0, 0
        sizes = [int(x) for x in re.findall(rb"(?:^|\n)  size: (\d+)\t", r.stdout or b"")]
        return sum(sizes), len(sizes)

def _parse_index_bytes(data):
    if len(data) < 12 or data[:4] != b"DIRC":
        raise ValueError("bad index")
    version, count = struct.unpack(">II", data[4:12])
    offset = 12
    total = 0
    prev_name = b""
    for _ in range(count):
        if offset + 62 > len(data):
            raise ValueError("short index")
        file_size = struct.unpack(">I", data[offset + 40:offset + 44])[0]
        flags = struct.unpack(">H", data[offset + 60:offset + 62])[0]
        total += file_size
        name_len = flags & 0x0FFF
        if version == 4:
            # OFS-delta varint for prefix compression
            pos = offset + 62
            strip = data[pos]
            pos += 1
            while data[pos - 1] & 0x80:
                strip = ((strip + 1) << 7) | (data[pos] & 0x7F)
                pos += 1
            end = data.index(b"\x00", pos)
            suffix = data[pos:end]
            prev_name = prev_name[: len(prev_name) - strip] + suffix if strip <= len(prev_name) else suffix
            offset = end + 1
        else:
            header = 62
            if version == 3 and (flags & 0x4000):
                header = 64
            if name_len < 0x0FFF:
                namelen = name_len
            else:
                end = data.index(b"\x00", offset + header)
                namelen = end - (offset + header)
            entry_len = ((header + namelen + 1) + 7) // 8 * 8
            offset += entry_len
    return total, count

def get_title(workdir):
    username = ""
