def traverse_commits(workdir, gitdir):
    # Reproduce the empty-repository / bad-HEAD errors first.
    head_path = os.path.join(gitdir, "HEAD")
    head_ref = None
    head_oid = None
    try:
        head_content = Path(head_path).read_text(encoding="utf-8", errors="replace").strip()
    except OSError:
        head_content = ""
    if head_content.startswith("ref:"):
        head_ref = head_content[4:].strip()
    elif re.fullmatch(r"[0-9a-fA-F]{40}([0-9a-fA-F]{24})?", head_content):
        head_oid = head_content
    fmt = "%H%x1f%P%x1f%ct%x1f%aN%x1f%aE%x1e"
    r = run_git(["log", f"--format={fmt}", "HEAD"], workdir)
    if r.returncode != 0:
        if head_ref:
            cause = f"Branch '{head_ref}' does not have any commits"
        elif head_oid:
            # Is the object present?
            t = run_git(["cat-file", "-t", head_oid], workdir)
            if t.returncode != 0:
                cause = f"An object with id {head_oid} could not be found"
            else:
                cause = (r.stderr or "").strip().splitlines()[-1] if (r.stderr or "").strip() else "could not parse HEAD"
        else:
            errtxt = (r.stderr or "").strip()
            cause = errtxt.splitlines()[-1] if errtxt else "could not parse HEAD"
        raise AppError("Failed to traverse Git commit history", [cause])
    commits = []
    for record in (r.stdout or "").split("\x1e"):
        record = record.strip("\n")
        if not record:
            continue
        parts = record.split("\x1f")
        if len(parts) < 5:
            continue
        h, parents, ct, an, ae = parts[:5]
        commits.append({
            "hash": h,
            "parents": parents.split() if parents else [],
            "time": int(ct) if ct.lstrip("-").isdigit() else 0,
            "author_name": an,
            "author_email": ae,
        })
    if not commits:
        if head_ref:
            raise AppError("Failed to traverse Git commit history", [f"Branch '{head_ref}' does not have any commits"])
