    return commits

def get_head_info(workdir):
    short = git_stdout(["rev-parse", "--short", "HEAD"], workdir)
    short = short.rstrip("\n") if short else ""
    sym = run_git(["symbolic-ref", "-q", "HEAD"], workdir)
    refs = []
    if sym.returncode == 0:
        full = (sym.stdout or "").rstrip("\n")
        shorthand = full
        for prefix in ("refs/heads/", "refs/remotes/", "refs/tags/"):
            if shorthand.startswith(prefix):
                shorthand = shorthand[len(prefix):]
                break
        refs.append(shorthand)
        # Upstream remote ref, included only when the configured merge
        # ref names the same branch (matching observed behaviour).
        if full.startswith("refs/heads/"):
            local = full[len("refs/heads/"):]
            upstream = None
            for selector in (f"{local}@{{upstream}}", f"{local}@{{push}}"):
                u = run_git(["rev-parse", "--symbolic-full-name", selector], workdir)
                if u.returncode == 0:
                    cand = (u.stdout or "").rstrip("\n")
                    if cand.startswith("refs/remotes/"):
                        upstream = cand
                        break
            if upstream:
                merge_ref = git_stdout(["config", f"branch.{local}.merge"], workdir)
                merge_short = None
                if merge_ref:
                    mr = merge_ref.rstrip("\n")
                    merge_short = mr[len("refs/heads/"):] if mr.startswith("refs/heads/") else mr
                if merge_short == local:
                    refs.append(upstream[len("refs/remotes/"):])
    return {"shortCommitId": short, "refs": refs}

def get_pending(workdir):
    added = deleted = modified = 0
    r = run_git(["status", "--porcelain=v1", "-z", "--untracked-files=all"], workdir, text=False)
    if r.returncode != 0:
        return added, deleted, modified
    raw = r.stdout or b""
    entries = raw.split(b"\x00")
    idx = 0
    while idx < len(entries):
        entry = entries[idx]
        idx += 1
        if len(entry) < 3:
            continue
        x, y = chr(entry[0]), chr(entry[1])
        if x in "RC" or y in "RC":
            idx += 1  # orig path follows
        if x == "?" and y == "?":
            added += 1
        elif x == "!" and y == "!":
            continue
        elif y == "D":
            deleted += 1
        elif y in ("M", "T", "R", "C"):
            modified += 1
        elif y == "A":
            added += 1
    return added, deleted, modified

def get_churn(workdir, commits, pool_size, number_of_file_churns):
    # commits: already filtered (merges/bots per flags) in revwalk order
    if pool_size is None:
        take = 1
    else:
        take = max(1, pool_size)
    selected = commits[:take]
    actual_pool = len(selected)
    counts = {}
    appearance = []
    for commit in selected:
        if len(commit.get("parents") or []) > 1:
            continue  # merge commits contribute no churn
        r = run_git(
            ["diff-tree", "-r", "--no-commit-id", "--name-status", "-z", "--root", "--no-renames", commit["hash"]],
            workdir, text=False,
        )
        if r.returncode != 0:
            # Shallow boundary etc.: diff against the empty tree
            empty = "4b825dc642cb6eb9a060e54bf8d69288fbee4904"
            r = run_git(["diff-tree", "-r", "--no-commit-id", "--name-status", "-z", "--no-renames", empty, commit["hash"]], workdir, text=False)
            if r.returncode != 0:
                continue
        parts = (r.stdout or b"").split(b"\x00")
        i = 0
        while i < len(parts):
            status = parts[i].decode("utf-8", "replace")
            i += 1
            if not status:
                continue
            code = status[0]
            if code in ("R", "C"):
                if i + 1 >= len(parts):
                    break
                _old = parts[i]
                newp = parts[i + 1].decode("utf-8", "replace")
                i += 2
                path = newp
                if path not in counts:
                    appearance.append(path)
                counts[path] = counts.get(path, 0) + 1
            else:
                if i >= len(parts):
                    break
                path = parts[i].decode("utf-8", "replace")
                i += 1
                if code == "D":
                    continue
                if path not in counts:
                    appearance.append(path)
                counts[path] = counts.get(path, 0) + 1
    items = [(p, counts[p]) for p in appearance]
    items.sort(key=lambda x: -x[1])
    items = items[:number_of_file_churns]
    file_churns = [{"filePath": p, "nbrOfCommits": c} for p, c in items]
    return file_churns, actual_pool

