                    out.append(" " * indent + f"- {key0}: {_yaml_scalar(v0)}")
                for k, v in items[1:]:
                    key = _yaml_scalar(k)
                    if isinstance(v, dict) and v:
                        out.append(" " * (indent + 2) + f"{key}:")
                        _yaml_emit(v, indent + 4, out)
                    elif isinstance(v, list) and v:
                        out.append(" " * (indent + 2) + f"{key}:")
                        _yaml_emit(v, indent + 2, out)
                    elif isinstance(v, dict):
                        out.append(" " * (indent + 2) + f"{key}: {{}}")
                    elif isinstance(v, list):
                        out.append(" " * (indent + 2) + f"{key}: []")
                    else:
                        out.append(" " * (indent + 2) + f"{key}: {_yaml_scalar(v)}")
            elif isinstance(item, list):
                out.append(" " * indent + "-")
                _yaml_emit(item, indent + 2, out)
            else:
                out.append(" " * indent + f"- {_yaml_scalar(item)}")
    else:
        out.append(" " * indent + _yaml_scalar(value))

def to_yaml(info):
    out = []
    _yaml_emit(serializable(info), 0, out)
    return "\n".join(out) + "\n"

# ---------------------------------------------------------------------------
# Image loading (errors reproduced; terminal rendering is best-effort)
# ---------------------------------------------------------------------------

_UNSUPPORTED_IMAGE_FORMATS = {
    "avif": "Avif", "bmp": "Bmp", "dds": "Dds", "exr": "OpenExr",
    "ff": "Farbfeld", "gif": "Gif", "hdr": "Hdr", "ico": "Ico",
    "pam": "Pnm", "pbm": "Pnm", "pgm": "Pnm", "ppm": "Pnm", "pnm": "Pnm",
    "qoi": "Qoi", "tga": "Tga", "tif": "Tiff", "tiff": "Tiff",
}

def load_image(image_path):
    data = None
    is_dir = os.path.isdir(image_path)
    if not is_dir:
        try:
            with open(image_path, "rb") as fh:
                data = fh.read()
        except OSError as exc:
            raise AppError(
                f"Could not load the image file at '{image_path}'",
                [f"{exc.strerror} (os error {exc.errno})"],
            )
    name = os.path.basename(image_path)
    ext = ""
    if "." in name:
        head, _, tail = name.rpartition(".")
        if head:
            ext = tail.lower()
    if not ext:
        raise AppError(f"Could not load the image file at '{image_path}'", ["The image format could not be determined"])
    if ext in _UNSUPPORTED_IMAGE_FORMATS:
        raise AppError(
            f"Could not load the image file at '{image_path}'",
            [f"The image format {_UNSUPPORTED_IMAGE_FORMATS[ext]} is not supported"],
        )
    if ext in ("png",):
        if data is None or not data.startswith(b"\x89PNG\r\n\x1a\n"):
            raise AppError(
                f"Could not load the image file at '{image_path}'",
                ["Format error decoding Png: Invalid PNG signature.", "Invalid PNG signature."],
            )
    elif ext in ("jpg", "jpeg", "jfif"):
        if data is None or len(data) < 2 or data[:2] != b"\xff\xd8":
            start = (data[:2] if data else b"").hex()
            raise AppError(
                f"Could not load the image file at '{image_path}'",
                [f"Format error decoding Jpeg: Error parsing image. Illegal start bytes:{start}", f"Error parsing image. Illegal start bytes:{start}"],
            )
    elif ext in ("webp",):
        if data is None or len(data) < 12:
            raise AppError(f"Could not load the image file at '{image_path}'", ["failed to fill whole buffer"])
        if not (data[:4] == b"RIFF" and data[8:12] == b"WEBP"):
            raise AppError(f"Could not load the image file at '{image_path}'", ["Format error decoding WebP: Invalid WebP signature.", "Invalid WebP signature."])
    else:
        raise AppError(
            f"Could not load the image file at '{image_path}'",
            [f'The file extension `."{ext}"` was not recognized as an image format'],
        )
    return data

def handle_image(args):
    image_path = args.get("image")
    data = load_image(image_path)
    if not sys.stdout.isatty():
        if args.get("image_protocol") is None:
            raise AppError("Failed to recieve terminal attibutes", ["Inappropriate ioctl for device (os error 25)"])
        raise AppError("Failed to render image", ["Inappropriate ioctl for device (os error 25)"])
    return data

