_ANSI_CYCLE = ["31", "32", "33", "34", "35", "36"]

def _language_lines(languages, args, truecolor, c_info):
    n = args.get("number_of_languages", 6)
    shown = list(languages[:n])
    other_pct = None
    if len(languages) > n:
        other_pct = sum(pct for _s, _c, pct in languages[n:])
    items = []  # (pretty_name, pct, serde_or_None)
    for serde, _code, pct in shown:
        lang = LANG_BY_SERDE.get(serde) or {}
        items.append((lang.get("pretty") or serde, pct, serde))
    if other_pct is not None:
        items.append(("Other", other_pct, None))

    def chip_fg(index, serde):
        if serde is None:
            return "37"
        if truecolor:
            lang = LANG_BY_SERDE.get(serde) or {}
            chip = lang.get("chip")
            if chip:
                return f"38;2;{chip[0]};{chip[1]};{chip[2]}"
            return "37"
        return _ANSI_CYCLE[index % len(_ANSI_CYCLE)]

    # Bar
    bar_parts = []
    for idx, (_name, pct, serde) in enumerate(items):
        width = max(1, rust_round((pct / 100.0) * 26.0))
        bg = fg_to_bg(chip_fg(idx, serde)) if truecolor else (
            "47" if serde is None else str(int(_ANSI_CYCLE[idx % len(_ANSI_CYCLE)]) + 10)
        )
        bar_parts.append(style_bg_spaces(width, bg))
    lines = ["".join(bar_parts)]

    # Chips, two per line
    entries = []
    for idx, (name, pct, serde) in enumerate(items):
        fg = chip_fg(idx, serde)
        icon = "●"
        if args.get("nerd_fonts") and serde is not None:
            lang = LANG_BY_SERDE.get(serde) or {}
            icon = lang.get("icon") or "●"
        entry = (
            f"\x1b[{fg}m{icon}\x1b[39m "
            + f"\x1b[{c_info}m{name} ({pct:.1f} %)\x1b[39m"
        )
        entries.append(entry)
    for i in range(0, len(entries), 2):
        chunk = entries[i:i + 2]
        if len(chunk) == 2:
            lines.append(chunk[0] + " " + chunk[1])
        else:
            lines.append(chunk[0] + " ")
    return lines

