# ---------------------------------------------------------------------------
# Text printer
# ---------------------------------------------------------------------------

def _parse_custom_art(text, bold=True):
    """Returns (rendered_lines, width).  Raises PanicAscii for empty art.
    Rendered lines are not yet padded; each entry is (rendered, visible_len).
    Colouring is applied later by the caller-supplied resolver, so this
    function instead returns segments."""
    # Split like Rust's str::lines (on \n, tolerating \r\n)
    raw_lines = text.split("\n")
    if text.endswith("\n") and raw_lines and raw_lines[-1] == "":
        raw_lines.pop()
    lines = []
    for idx, line in enumerate(raw_lines):
        if idx < len(raw_lines) - 1 and line.endswith("\r"):
            line = line[:-1]
        lines.append(line)
    # Skip leading empty lines
    start_idx = 0
    while start_idx < len(lines) and lines[start_idx] == "":
        start_idx += 1
    lines = lines[start_idx:]

    token_re = re.compile(r"\{([0-9])\}")
    parsed = []  # list of list of (color_idx_or_None, text, col_start)
    visibles = []
    for line in lines:
        segs = []
        col = 0
        pos = 0
        cur_idx = None
        cur_start = 0
        it = list(token_re.finditer(line))
        if not it:
            segs.append((None, line, 0))
            visibles.append(line)
            parsed.append(segs)
            continue
        visible = []
        for m in it:
            seg_text = line[pos:m.start()]
            segs.append((cur_idx, seg_text, cur_start))
            visible.append(seg_text)
            col += len(seg_text)
            cur_idx = int(m.group(1))
            cur_start = col
            pos = m.end()
        tail = line[pos:]
        segs.append((cur_idx, tail, cur_start))
        visible.append(tail)
        visibles.append("".join(visible))
        parsed.append(segs)

    firsts = []
    lasts = []
    last_row = -1
    for r, visible in enumerate(visibles):
        first = None
        last = None
        for c, ch in enumerate(visible):
            if ch != " ":
                if first is None:
                    first = c
                last = c
        if first is not None:
            firsts.append(first)
            lasts.append(last)
            last_row = r
    if not firsts:
        raise PanicAscii()
    start = min(firsts)
    end = max(lasts)
    width = end - start + 1
    parsed = parsed[: last_row + 1]
    visibles = visibles[: last_row + 1]

    cropped = []
    for segs in parsed:
        new_segs = []
        for idx, (cidx, text_seg, col_start) in enumerate(segs):
            seg_start = col_start
            seg_end = col_start + len(text_seg)
            if len(text_seg) == 0:
                # Keep zero-width segments unless they sit strictly past
                # the right edge as the final segment.
                if seg_start > end and idx == len(segs) - 1 and seg_start != 0:
                    continue
                new_segs.append((cidx, ""))
                continue
            lo = max(seg_start, start)
            hi = min(seg_end, end + 1)
            if lo >= hi:
                continue
            new_segs.append((cidx, text_seg[lo - seg_start: hi - seg_start]))
        cropped.append(new_segs)
    return cropped, width

def _render_art_segments(lines, colors, bold):
    rendered = []
    width = 0
    vis_lens = []
    for segs in lines:
        vis = sum(len(t) for _i, t in segs)
        vis_lens.append(vis)
        width = max(width, vis)
    for segs, vis in zip(lines, vis_lens):
        parts = []
        for cidx, text_seg in segs:
            if cidx is None:
                code = "39"
            elif cidx < len(colors):
                code = colors[cidx]
            else:
                code = "39"
            parts.append(style_bold(text_seg, code, bold=bold))
        rendered.append(("".join(parts), vis))
    return rendered, width

