def _color_long_usage(text):
    m = re.match(r"--[A-Za-z0-9][A-Za-z0-9-]*", text)
    if not m:
        return _cg(text)
    out = _cg(m.group(0))
    rest = text[m.end():]
    if rest.startswith(" "):
        out += _cg(" ") + _cg(rest[1:])
    elif rest.startswith("[="):
        end = rest.find("]")
        if end == -1:
            out += _cg(rest)
        else:
            out += _cg("[=") + _cg(rest[2:end]) + _cg("]")
            if rest[end + 1:]:
