new='''def _format_rust_f64(v):
    if v == 0.0:
        return "0.0"
    from decimal import Decimal
    sign = "-" if v < 0 else ""
    d = Decimal(repr(abs(v)))
    tup = d.as_tuple()
    digits = "".join(str(x) for x in tup.digits) or "0"
    exp = tup.exponent
    point = len(digits) + exp
    sci_exp = point - 1
    if sci_exp <= -6 or sci_exp >= 21:
        mantissa = digits[0] + ("." + digits[1:] if len(digits) > 1 else "")
        return f"{sign}{mantissa}e{sci_exp}"
    if point <= 0:
        return f"{sign}0." + ("0" * (-point)) + digits
    if point >= len(digits):
        return f"{sign}{digits}" + ("0" * (point - len(digits))) + ".0"
    return f"{sign}{digits[:point]}.{digits[point:]}"

def _json_dump(obj, level=0):
    indent = "  " * level
    child_indent = "  " * (level + 1)
    if obj is None:
        return "null"
    if obj is True:
        return "true"
    if obj is False:
        return "false"
    if isinstance(obj, float):
        return _format_rust_f64(obj)
    if isinstance(obj, int):
        return str(obj)
    if isinstance(obj, str):
        return json.dumps(obj, ensure_ascii=False)
    if isinstance(obj, list):
        if not obj:
            return "[]"
        items = [child_indent + _json_dump(v, level + 1) for v in obj]
        return "[\\n" + ",\\n".join(items) + "\\n" + indent + "]"
    if isinstance(obj, dict):
        if not obj:
            return "{}"
        items = [
            child_indent + json.dumps(str(k), ensure_ascii=False) + ": " + _json_dump(v, level + 1)
            for k, v in obj.items()
        ]
        return "{\\n" + ",\\n".join(items) + "\\n" + indent + "}"
    return json.dumps(obj, ensure_ascii=False)

def to_json(info):
    return _json_dump(serializable(info))'''
