    try:
        try:
            import tomllib as _toml
        except Exception:
            import tomli as _toml
        data = _toml.loads(text)
    except Exception:
        return None
    if not isinstance(data, dict):
        return None
    package = data.get("package")
    if not isinstance(package, dict):
        return None
    name = package.get("name")
    if not isinstance(name, str):
        return None
    workspace = data.get("workspace") if isinstance(data.get("workspace"), dict) else {}
    ws_pkg = workspace.get("package") if isinstance(workspace, dict) else None

    def resolve(value, key):
        if isinstance(value, dict) and "workspace" in value:
            if value.get("workspace") is not True:
                return None, False
            if isinstance(ws_pkg, dict) and key in ws_pkg:
                return ws_pkg[key], True
            return None, False
        return value, True

    # Validate well-known package fields the way cargo_toml does.
    _str_fields = {"rust-version", "description", "homepage", "documentation", "repository", "license", "license-file", "links", "default-run", "resolver", "workspace"}
    _list_fields = {"authors", "keywords", "categories", "exclude", "include"}
    _bool_fields = {"autobins", "autoexamples", "autotests", "autobenches"}
    for _key, _raw in package.items():
        if _key in ("name", "version"):
            continue
        _val, _ok = resolve(_raw, _key)
        if not _ok:
            return None
        if _key == "edition":
            if _val not in ("2015", "2018", "2021", "2024"):
                return None
        elif _key in _str_fields:
            if not isinstance(_val, str):
                return None
        elif _key in _list_fields:
            if not (isinstance(_val, list) and all(isinstance(x, str) for x in _val)):
                return None
        elif _key in _bool_fields:
            if not isinstance(_val, bool):
                return None
        elif _key == "publish":
            if not (isinstance(_val, bool) or (isinstance(_val, list) and all(isinstance(x, str) for x in _val))):
                return None
        elif _key == "readme":
            if not (isinstance(_val, (str, bool)) or (isinstance(_val, dict) and isinstance(_val.get("file"), str))):
                return None
        elif _key == "build":
            if not isinstance(_val, (str, bool)):
                return None

    def field(key):
        if key not in package:
            return None, True
        return resolve(package.get(key), key)

    desc, ok = field("description")
    if not ok or (desc is not None and not isinstance(desc, str)):
        return None
    lic, ok = field("license")
    if not ok or (lic is not None and not isinstance(lic, str)):
        return None
    ver, ok = field("version")
    if not ok or (ver is not None and not isinstance(ver, str)):
        return None

    ws_deps = workspace.get("dependencies") if isinstance(workspace, dict) else None

    def valid_dep(dep_name, dep_val):
        if isinstance(dep_val, str):
            return True
        if not isinstance(dep_val, dict):
            return False
        if "workspace" in dep_val:
            if dep_val.get("workspace") is not True:
                return False
            if not isinstance(ws_deps, dict) or dep_name not in ws_deps:
                return False
        _dep_str = {"version", "path", "git", "branch", "tag", "rev", "registry", "registry-index", "package"}
        _dep_bool = {"optional", "default-features", "workspace"}
        for _k, _v in dep_val.items():
            if _k in _dep_str and not isinstance(_v, str):
                return False
            if _k in _dep_bool and not isinstance(_v, bool):
                return False
            if _k == "features" and not (isinstance(_v, list) and all(isinstance(x, str) for x in _v)):
                return False
        return True

    deps = data.get("dependencies")
    if deps is None:
        count = 0
    elif isinstance(deps, dict):
        if not all(valid_dep(k, v) for k, v in deps.items()):
            return None
        count = len(deps)
    else:
        return None
    return {
        "manager": "Cargo",
        "description": desc,
        "license": lic,
        "version": ver if ver is not None else "0.0.0",
        "dep_count": count,
    }
'''
