                break

    def parse(self):
        root = {}
        current = root
        while True:
            self.skip_ws(newlines=True)
            if self.i >= self.n:
                return root
            if self.peek() == "[":
                self.i += 1
                is_array = False
                if self.peek() == "[":
                    is_array = True
                    self.i += 1
                self.skip_ws()
                keys = self.parse_key_path()
                self.skip_ws()
                if self.peek() != "]":
                    self.err()
                self.i += 1
                if is_array:
                    if self.peek() != "]":
                        self.err()
                    self.i += 1
                current = self._navigate(root, keys, create_list=is_array)
            else:
                keys = self.parse_key_path()
                self.skip_ws()
                if self.peek() != "=":
                    self.err()
                self.i += 1
                self.skip_ws()
                value = self.parse_value()
                self._assign(current, keys, value)
            self.skip_ws()
            if self.i < self.n and self.s[self.i] == "#":
                while self.i < self.n and self.s[self.i] != "\n":
                    self.i += 1
            if self.i < self.n and self.s[self.i] not in "\r\n":
                self.err()

    def _navigate(self, root, keys, create_list=False):
        cur = root
        for key in keys[:-1]:
            nxt = cur.get(key)
            if isinstance(nxt, list):
                if not nxt:
                    nxt.append({})
                cur = nxt[-1]
            elif isinstance(nxt, dict):
                cur = nxt
            elif nxt is None:
                nxt = {}
                cur[key] = nxt
                cur = nxt
            else:
                self.err()
        last = keys[-1]
        if create_list:
            lst = cur.get(last)
            if lst is None:
                lst = []
                cur[last] = lst
            if not isinstance(lst, list):
                self.err()
            item = {}
            lst.append(item)
            return item
        nxt = cur.get(last)
        if isinstance(nxt, list):
            if not nxt:
                nxt.append({})
            return nxt[-1]
        if nxt is None:
            nxt = {}
            cur[last] = nxt
        if not isinstance(nxt, dict):
            self.err()
        return nxt

    def _assign(self, table, keys, value):
        cur = table
        for key in keys[:-1]:
            nxt = cur.get(key)
            if nxt is None:
                nxt = {}
                cur[key] = nxt
            if not isinstance(nxt, dict):
                self.err()
            cur = nxt
        if keys[-1] in cur:
            self.err()
        cur[keys[-1]] = value

    def parse_key_path(self):
        keys = []
        while True:
            self.skip_ws()
            if self.peek() in ('"', "'"):
                keys.append(self.parse_string())
            else:
                start = self.i
                while self.i < self.n and (self.s[self.i].isalnum() or self.s[self.i] in "_-"):
                    self.i += 1
                if self.i == start:
                    self.err()
                keys.append(self.s[start:self.i])
            self.skip_ws()
            if self.peek() == ".":
                self.i += 1
                continue
            return keys

    def parse_string(self):
        quote = self.peek()
        if self.s.startswith(quote * 3, self.i):
            self.i += 3
            end = self.s.find(quote * 3, self.i)
            if end == -1:
                self.err()
            raw = self.s[self.i:end]
            self.i = end + 3
            if raw.startswith("\n"):
                raw = raw[1:]
            if quote == '"':
                return self._unescape(raw)
            return raw
        self.i += 1
        out = []
        while self.i < self.n:
            ch = self.s[self.i]
            if ch == quote:
                self.i += 1
                return "".join(out)
            if ch == "\n":
                self.err()
            if quote == '"' and ch == "\\":
                if self.i + 1 >= self.n:
                    self.err()
                out.append(self.s[self.i:self.i + 2])
                self.i += 2
                continue
            out.append(ch)
            self.i += 1
        self.err()

    def _unescape(self, raw):
        result = []
        i = 0
        escapes = {"n": "\n", "t": "\t", "r": "\r", '"': '"', "\\": "\\", "b": "\b", "f": "\f", "/": "/"}
        while i < len(raw):
            if raw[i] == "\\" and i + 1 < len(raw):
                nxt = raw[i + 1]
                if nxt in escapes:
                    result.append(escapes[nxt])
                    i += 2
                elif nxt == "u" and i + 5 < len(raw) + 1:
                    try:
                        result.append(chr(int(raw[i + 2:i + 6], 16)))
                        i += 6
                    except Exception:
                        self.err()
                elif nxt == "U" and i + 9 < len(raw) + 1:
                    try:
                        result.append(chr(int(raw[i + 2:i + 10], 16)))
                        i += 10
                    except Exception:
                        self.err()
                elif nxt in "\n\r":
                    i += 2
                    while i < len(raw) and raw[i] in " \t\r\n":
                        i += 1
                else:
                    self.err()
            else:
                result.append(raw[i])
                i += 1
        return "".join(result)

    def parse_value(self):
        ch = self.peek()
        if ch in ('"', "'"):
            if ch == '"' and not self.s.startswith('"""', self.i):
                # Reuse parse_string but unescape basic strings
                value = self.parse_string()
                return self._unescape(value) if "\\" in value else value
            return self.parse_string()
        if ch == "[":
            self.i += 1
            arr = []
            while True:
                self.skip_ws(newlines=True)
                if self.peek() == "]":
                    self.i += 1
                    return arr
                arr.append(self.parse_value())
                self.skip_ws(newlines=True)
                if self.peek() == ",":
                    self.i += 1
                    continue
                if self.peek() == "]":
                    self.i += 1
                    return arr
                self.err()
        if ch == "{":
            self.i += 1
            table = {}
            while True:
                self.skip_ws()
                if self.peek() == "}":
                    self.i += 1
                    return table
                keys = self.parse_key_path()
                self.skip_ws()
                if self.peek() != "=":
                    self.err()
                self.i += 1
                self.skip_ws()
                self._assign(table, keys, self.parse_value())
                self.skip_ws()
                if self.peek() == ",":
                    self.i += 1
                    continue
                if self.peek() == "}":
                    self.i += 1
                    return table
                self.err()
        start = self.i
        while self.i < self.n and self.s[self.i] not in ",]}#\n":
            self.i += 1
        token = self.s[start:self.i].strip()
        if token == "true":
            return True
        if token == "false":
            return False
        cleaned = token.replace("_", "")
        try:
            return int(cleaned, 0)
        except ValueError:
            pass
        try:
            return float(cleaned)
        except ValueError:
            pass
        if not token:
            self.err()
        return token

